class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        counts.put(0, 1);
        int running = 0;
        int answer = 0;
        for (int num : nums) {
            running += num;
            answer += counts.getOrDefault(running - k, 0);
            counts.merge(running, 1, Integer::sum);
        }
        return answer;
    }
}
